 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    known = {}
    offsets = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                offsets.append(d)
                if d in known and known[d] != value:
                    raise ValueError("non-constant diagonal")
                known[d] = value
    # The clues are colored diagonals from a cyclic diagonal stripe pattern.
    # Choose the shortest cycle consistent with every clue.
    period = None
    residues = None
    for p in range(1, max(h, w) + 1):
        colors = {}
        valid = True
        for d, value in known.items():
            k = d % p
            if k in colors and colors[k] != value:
                valid = False
                break
            colors[k] = value
        if valid:
            period, residues = p, colors
            break
    if period is None:
        raise ValueError("no cyclic stripe pattern")
    # A valid inferred cycle fills each residue; for incomplete clue sets extend
    # by the nearest known phase, preserving cyclic order.
    if len(residues) < period:
        keys = sorted(residues)
        for k in range(period):
            if k not in residues:
                residues[k] = residues[min(keys, key=lambda x: min((x-k) % period, (k-x) % period))]
    return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
